"use client";

import { useMemo, useState } from "react";
import { useRouter } from "next/navigation";
import { AlertCircle, Check, MessageSquareText, ShoppingCart, Zap } from "lucide-react";
import type { PlatformId, Product } from "@/lib/types";
import { Button, ButtonLink } from "@/components/ui/Button";
import { PlatformIcon } from "@/components/product/PlatformIcons";
import {
  createCartItem,
  defaultPlatform,
  defaultSelection,
  toggleChoice,
  validateSelection,
  type OptionSelection,
} from "@/lib/product-utils";
import { useCart } from "@/lib/cart-context";
import { discordHref } from "@/lib/links";
import { cn, formatPrice, getPlatformLabel } from "@/lib/utils";
import { platforms } from "@/config/site";

export function ProductConfigurator({
  product,
  compact = false,
  showBuyNow = true,
  showTicketButton = true,
  onAdded,
}: {
  product: Product;
  compact?: boolean;
  showBuyNow?: boolean;
  showTicketButton?: boolean;
  onAdded?: () => void;
}) {
  const router = useRouter();
  const { addItem, currency } = useCart();
  const [platform, setPlatform] = useState<PlatformId>(() =>
    defaultPlatform(product),
  );
  const [selection, setSelection] = useState<OptionSelection>(() =>
    defaultSelection(product),
  );
  const [quantity, setQuantity] = useState(1);
  const [errors, setErrors] = useState<string[]>([]);
  const [added, setAdded] = useState(false);

  const supported = useMemo(
    () => platforms.filter((entry) => product.supportedPlatforms.includes(entry.id)),
    [product.supportedPlatforms],
  );

  function handleAdd(): boolean {
    const validation = validateSelection(product, selection);
    setErrors(validation);
    if (validation.length > 0) return false;
    addItem(createCartItem(product, platform, selection, quantity));
    setAdded(true);
    window.setTimeout(() => setAdded(false), 2200);
    onAdded?.();
    return true;
  }

  const errorId = `configurator-errors-${product.id}`;

  return (
    <div className="flex flex-col gap-6">
      {/* Platform ------------------------------------------------------- */}
      <fieldset>
        <legend className="text-[11px] font-medium uppercase tracking-[0.18em] text-silver-500">
          Platform
        </legend>
        <div className="mt-3 flex flex-wrap gap-2">
          {supported.map((entry) => {
            const selected = platform === entry.id;
            return (
              <button
                key={entry.id}
                type="button"
                onClick={() => setPlatform(entry.id)}
                aria-pressed={selected}
                className={cn(
                  "inline-flex items-center gap-2 rounded-lg border px-3.5 py-2.5 text-[13px] font-medium transition",
                  selected
                    ? "border-violet-300/45 bg-violet-500/12 text-white shadow-[0_0_0_1px_rgba(171,151,238,0.15)]"
                    : "border-white/10 bg-white/[0.03] text-silver-300 hover:border-white/25 hover:text-white",
                )}
              >
                <PlatformIcon platform={entry.id} className="h-4 w-4" />
                {getPlatformLabel(entry.id)}
                {selected ? (
                  <Check className="h-3.5 w-3.5 text-violet-200" aria-hidden="true" />
                ) : null}
              </button>
            );
          })}
        </div>
        {supported.find((entry) => entry.id === platform)?.note ? (
          <p className="mt-2 text-[12px] text-silver-500">
            {supported.find((entry) => entry.id === platform)?.note}
          </p>
        ) : null}
      </fieldset>

      {/* Options -------------------------------------------------------- */}
      {product.options.map((group) => (
        <fieldset key={group.id}>
          <legend className="flex flex-wrap items-center gap-2 text-[11px] font-medium uppercase tracking-[0.18em] text-silver-500">
            {group.label}
            {group.required ? (
              <span className="rounded border border-violet-300/25 px-1.5 py-0.5 text-[9px] tracking-[0.1em] text-violet-200">
                Required
              </span>
            ) : null}
          </legend>
          {group.helpText ? (
            <p className="mt-2 text-[12.5px] text-silver-400">{group.helpText}</p>
          ) : null}
          <div
            className={cn(
              "mt-3 grid gap-2",
              compact ? "sm:grid-cols-2" : "sm:grid-cols-2",
            )}
          >
            {group.choices.map((choice) => {
              const selected = (selection[group.id] ?? []).includes(choice.id);
              return (
                <button
                  key={choice.id}
                  type="button"
                  onClick={() => {
                    setSelection((current) =>
                      toggleChoice(current, group.id, choice.id, group.type),
                    );
                    setErrors([]);
                  }}
                  aria-pressed={selected}
                  className={cn(
                    "flex items-start gap-2.5 rounded-lg border px-3.5 py-3 text-left transition",
                    selected
                      ? "border-violet-300/40 bg-violet-500/10"
                      : "border-white/10 bg-white/[0.02] hover:border-white/22 hover:bg-white/[0.05]",
                  )}
                >
                  <span
                    aria-hidden="true"
                    className={cn(
                      "mt-0.5 grid h-4 w-4 shrink-0 place-items-center border transition",
                      group.type === "single" ? "rounded-full" : "rounded-[5px]",
                      selected
                        ? "border-violet-200 bg-violet-400/80"
                        : "border-white/25 bg-transparent",
                    )}
                  >
                    {selected ? (
                      <Check className="h-2.5 w-2.5 text-[#0b0b12]" strokeWidth={3.5} />
                    ) : null}
                  </span>
                  <span className="min-w-0">
                    <span className="block text-[13.5px] font-medium text-white">
                      {choice.label}
                    </span>
                    {choice.description ? (
                      <span className="mt-0.5 block text-[12px] leading-snug text-silver-400">
                        {choice.description}
                      </span>
                    ) : null}
                  </span>
                </button>
              );
            })}
          </div>
        </fieldset>
      ))}

      {/* Quantity ------------------------------------------------------- */}
      <div className="flex flex-wrap items-center gap-4">
        <div>
          <label
            htmlFor={`qty-${product.id}`}
            className="text-[11px] font-medium uppercase tracking-[0.18em] text-silver-500"
          >
            Quantity
          </label>
          <div className="mt-2.5 inline-flex items-center rounded-lg border border-white/10 bg-white/[0.03]">
            <button
              type="button"
              onClick={() => setQuantity((value) => Math.max(1, value - 1))}
              aria-label="Decrease quantity"
              className="h-10 w-10 rounded-l-lg text-silver-300 transition hover:bg-white/[0.07] hover:text-white"
            >
              −
            </button>
            <input
              id={`qty-${product.id}`}
              type="number"
              min={1}
              max={99}
              value={quantity}
              onChange={(event) =>
                setQuantity(
                  Math.max(1, Math.min(99, Number(event.target.value) || 1)),
                )
              }
              className="h-10 w-12 bg-transparent text-center text-[14px] font-medium text-white outline-none"
            />
            <button
              type="button"
              onClick={() => setQuantity((value) => Math.min(99, value + 1))}
              aria-label="Increase quantity"
              className="h-10 w-10 rounded-r-lg text-silver-300 transition hover:bg-white/[0.07] hover:text-white"
            >
              +
            </button>
          </div>
        </div>

        <div className="ml-auto text-right">
          <p className="text-[11px] uppercase tracking-[0.18em] text-silver-500">
            Price
          </p>
          <p className="mt-1 text-[19px] font-semibold text-gold-200">
            {formatPrice(product.price, currency, product.quoteRequired)}
          </p>
        </div>
      </div>

      {errors.length > 0 ? (
        <div
          id={errorId}
          role="alert"
          className="flex gap-2 rounded-lg border border-red-500/25 bg-red-500/8 p-3 text-[13px] text-red-100"
        >
          <AlertCircle className="mt-0.5 h-4 w-4 shrink-0" aria-hidden="true" />
          <ul className="flex flex-col gap-1">
            {errors.map((error) => (
              <li key={error}>{error}</li>
            ))}
          </ul>
        </div>
      ) : null}

      {/* Actions -------------------------------------------------------- */}
      <div className="flex flex-col gap-2.5">
        <div className={cn("grid gap-2.5", showBuyNow && "sm:grid-cols-2")}>
          <Button
            onClick={handleAdd}
            size="lg"
            fullWidth
            aria-describedby={errors.length > 0 ? errorId : undefined}
          >
            {added ? (
              <>
                <Check className="h-4 w-4" aria-hidden="true" />
                Added to cart
              </>
            ) : (
              <>
                <ShoppingCart className="h-4 w-4" aria-hidden="true" />
                Add to Cart
              </>
            )}
          </Button>
          {showBuyNow ? (
            <Button
              variant="gold"
              size="lg"
              fullWidth
              onClick={() => {
                if (handleAdd()) router.push("/checkout");
              }}
            >
              <Zap className="h-4 w-4" aria-hidden="true" />
              Buy Now
            </Button>
          ) : null}
        </div>
        {showTicketButton ? (
          <ButtonLink href={discordHref} variant="outline" size="lg" fullWidth>
            <MessageSquareText className="h-4 w-4" aria-hidden="true" />
            Open Ticket
          </ButtonLink>
        ) : null}
        <p aria-live="polite" className="sr-only">
          {added ? `${product.title} added to your cart` : ""}
        </p>
      </div>
    </div>
  );
}
