"use client";

import { ArrowRight, Clock, Check } from "lucide-react";
import type { Product } from "@/lib/types";
import { Dialog } from "@/components/ui/Dialog";
import { ButtonLink } from "@/components/ui/Button";
import { ProductVisual } from "@/components/product/ProductVisual";
import { ProductConfigurator } from "@/components/product/ProductConfigurator";
import { ProductBadge } from "@/components/ui/Badge";
import { getCategoryTitle } from "@/config/categories";

export function QuickViewDialog({
  product,
  open,
  onClose,
}: {
  product: Product | null;
  open: boolean;
  onClose: () => void;
}) {
  if (!product) return null;

  return (
    <Dialog
      open={open}
      onClose={onClose}
      title={product.title}
      description={`${getCategoryTitle(product.category)} · ${product.subtitle}`}
      variant="modal"
      className="max-w-3xl"
      footer={
        <ButtonLink
          href={`/products/${product.slug}`}
          variant="outline"
          fullWidth
          onClick={onClose}
        >
          View full product page
          <ArrowRight className="h-4 w-4" aria-hidden="true" />
        </ButtonLink>
      }
    >
      <div className="grid gap-6 p-5 sm:p-6 md:grid-cols-2">
        <div className="flex flex-col gap-4">
          <div className="relative aspect-4/3 overflow-hidden rounded-xl border border-white/10">
            <ProductVisual
              visual={product.visual}
              label={`${product.title} artwork`}
              className="h-full w-full"
            />
            {product.badge ? (
              <div className="absolute left-3 top-3">
                <ProductBadge badge={product.badge} />
              </div>
            ) : null}
          </div>

          <p className="text-[13.5px] leading-relaxed text-silver-300">
            {product.description}
          </p>

          <p className="inline-flex items-center gap-2 text-[12.5px] text-silver-400">
            <Clock className="h-3.5 w-3.5" aria-hidden="true" />
            {product.deliveryEstimate}
          </p>

          <ul className="flex flex-col gap-2">
            {product.features.slice(0, 4).map((feature) => (
              <li key={feature} className="flex gap-2 text-[13px] text-silver-300">
                <Check
                  className="mt-0.5 h-3.5 w-3.5 shrink-0 text-violet-300"
                  aria-hidden="true"
                />
                {feature}
              </li>
            ))}
          </ul>
        </div>

        <ProductConfigurator
          product={product}
          compact
          showBuyNow={false}
          showTicketButton={false}
          onAdded={onClose}
        />
      </div>
    </Dialog>
  );
}
