import type {
  CartItem,
  CartSelectedOption,
  PlatformId,
  Product,
} from "@/lib/types";
import { buildCartKey } from "@/lib/utils";

/** groupId -> selected choice ids */
export type OptionSelection = Record<string, string[]>;

/** Pre-selects the first choice of every required single-select group. */
export function defaultSelection(product: Product): OptionSelection {
  const selection: OptionSelection = {};
  for (const group of product.options) {
    if (group.type === "single" && group.required && group.choices.length > 0) {
      selection[group.id] = [group.choices[0].id];
    } else {
      selection[group.id] = [];
    }
  }
  return selection;
}

export function defaultPlatform(product: Product): PlatformId {
  return product.supportedPlatforms[0] ?? "pc";
}

export function toggleChoice(
  selection: OptionSelection,
  groupId: string,
  choiceId: string,
  type: "single" | "multi",
): OptionSelection {
  const current = selection[groupId] ?? [];
  if (type === "single") {
    return { ...selection, [groupId]: [choiceId] };
  }
  return {
    ...selection,
    [groupId]: current.includes(choiceId)
      ? current.filter((id) => id !== choiceId)
      : [...current, choiceId],
  };
}

/** Human-readable option labels for the cart and order summary. */
export function buildSelectedOptions(
  product: Product,
  selection: OptionSelection,
): CartSelectedOption[] {
  const result: CartSelectedOption[] = [];
  for (const group of product.options) {
    const choiceIds = selection[group.id] ?? [];
    if (choiceIds.length === 0) continue;
    const choiceLabels = choiceIds
      .map((id) => group.choices.find((choice) => choice.id === id)?.label)
      .filter((label): label is string => Boolean(label));
    if (choiceLabels.length === 0) continue;
    result.push({
      groupId: group.id,
      groupLabel: group.label,
      choiceIds,
      choiceLabels,
    });
  }
  return result;
}

export function optionSignature(options: CartSelectedOption[]): string {
  return options
    .map((option) => `${option.groupId}:${[...option.choiceIds].sort().join(",")}`)
    .sort()
    .join("|");
}

/** Returns a message per unsatisfied required option group. */
export function validateSelection(
  product: Product,
  selection: OptionSelection,
): string[] {
  const errors: string[] = [];
  for (const group of product.options) {
    if (!group.required) continue;
    if ((selection[group.id] ?? []).length === 0) {
      errors.push(`Choose ${group.label.toLowerCase()} before continuing.`);
    }
  }
  return errors;
}

export function createCartItem(
  product: Product,
  platform: PlatformId,
  selection: OptionSelection,
  quantity = 1,
): CartItem {
  const options = buildSelectedOptions(product, selection);
  return {
    key: buildCartKey(product.id, platform, optionSignature(options)),
    productId: product.id,
    slug: product.slug,
    title: product.title,
    category: product.category,
    visual: product.visual,
    image: product.image ?? null,
    platform,
    options,
    quantity: Math.max(1, Math.min(99, Math.round(quantity) || 1)),
    price: product.price,
    quoteRequired: product.quoteRequired,
    deliveryEstimate: product.deliveryEstimate,
  };
}

/** Rebuilds an editable selection from a cart line. */
export function selectionFromCartItem(item: CartItem): OptionSelection {
  const selection: OptionSelection = {};
  for (const option of item.options) {
    selection[option.groupId] = [...option.choiceIds];
  }
  return selection;
}
