"use client";

import Link from "next/link";
import { useState } from "react";
import { Check, Clock, Eye, ShoppingCart } from "lucide-react";
import type { Product } from "@/lib/types";
import { ProductVisual } from "@/components/product/ProductVisual";
import { PlatformIcons } from "@/components/product/PlatformIcons";
import { ProductBadge } from "@/components/ui/Badge";
import { QuickViewDialog } from "@/components/product/QuickViewDialog";
import { getCategoryTitle } from "@/config/categories";
import { useCart } from "@/lib/cart-context";
import {
  createCartItem,
  defaultPlatform,
  defaultSelection,
} from "@/lib/product-utils";
import { cn, formatPrice } from "@/lib/utils";

export function ProductCard({
  product,
  className,
}: {
  product: Product;
  className?: string;
}) {
  const { addItem, currency } = useCart();
  const [quickOpen, setQuickOpen] = useState(false);
  const [mountedQuickView, setMountedQuickView] = useState(false);
  const [added, setAdded] = useState(false);

  function quickAdd() {
    addItem(
      createCartItem(
        product,
        defaultPlatform(product),
        defaultSelection(product),
        1,
      ),
    );
    setAdded(true);
    window.setTimeout(() => setAdded(false), 1800);
  }

  return (
    <>
      <article
        className={cn(
          "group relative flex h-full flex-col overflow-hidden rounded-2xl border border-white/8 bg-[#0a0a11] transition-[border-color,transform,box-shadow] duration-300 ease-[cubic-bezier(.22,.61,.36,1)]",
          "hover:-translate-y-1 hover:border-white/18 hover:shadow-[0_28px_70px_-40px_rgba(122,98,208,0.85)]",
          "focus-within:border-violet-300/35",
          className,
        )}
      >
        <div className="relative aspect-4/3 overflow-hidden">
          <ProductVisual
            visual={product.visual}
            label={`${product.title} artwork`}
            className="h-full w-full transition-transform duration-700 ease-[cubic-bezier(.22,.61,.36,1)] group-hover:scale-[1.04]"
          />

          {product.badge ? (
            <div className="absolute left-3 top-3">
              <ProductBadge badge={product.badge} />
            </div>
          ) : null}

          <button
            type="button"
            onClick={() => {
              setMountedQuickView(true);
              setQuickOpen(true);
            }}
            className="absolute right-3 top-3 inline-flex items-center gap-1.5 rounded-lg border border-white/12 bg-black/55 px-2.5 py-1.5 text-[11.5px] font-medium text-silver-100 backdrop-blur-sm transition hover:border-white/30 hover:bg-black/75"
          >
            <Eye className="h-3.5 w-3.5" aria-hidden="true" />
            Quick View
            <span className="sr-only"> of {product.title}</span>
          </button>

          <p className="absolute bottom-3 left-3 inline-flex items-center gap-1.5 rounded-lg border border-white/10 bg-black/50 px-2.5 py-1.5 text-[11px] text-silver-200 backdrop-blur-sm">
            <Clock className="h-3 w-3" aria-hidden="true" />
            {product.deliveryEstimate}
          </p>
        </div>

        <div className="flex flex-1 flex-col gap-3 p-4 sm:p-5">
          <div>
            <p className="text-[10.5px] font-medium uppercase tracking-[0.18em] text-violet-200/70">
              {getCategoryTitle(product.category)}
            </p>
            <h3 className="mt-1.5 text-[17px] font-semibold leading-snug text-white">
              <Link
                href={`/products/${product.slug}`}
                className="outline-none after:absolute after:inset-0 after:content-[''] focus-visible:underline"
              >
                {product.title}
              </Link>
            </h3>
            <p className="mt-1.5 line-clamp-2 text-[13px] leading-relaxed text-silver-400">
              {product.subtitle}. {product.description}
            </p>
          </div>

          <PlatformIcons platforms={product.supportedPlatforms} className="mt-auto" />

          <div className="flex items-end justify-between gap-3 border-t border-white/6 pt-3.5">
            <div>
              <p className="text-[10.5px] uppercase tracking-[0.16em] text-silver-500">
                {product.quoteRequired ? "Pricing" : "From"}
              </p>
              <p className="mt-0.5 text-[16px] font-semibold text-gold-200">
                {formatPrice(product.price, currency, product.quoteRequired)}
              </p>
            </div>
          </div>

          <div className="relative z-1 grid grid-cols-2 gap-2">
            <Link
              href={`/products/${product.slug}`}
              className="inline-flex h-10 items-center justify-center rounded-lg border border-white/12 bg-white/[0.03] text-[13px] font-medium text-silver-100 transition hover:border-white/25 hover:bg-white/[0.08] hover:text-white"
            >
              View Product
            </Link>
            <button
              type="button"
              onClick={quickAdd}
              className="inline-flex h-10 items-center justify-center gap-1.5 rounded-lg border border-violet-400/40 bg-[linear-gradient(140deg,#7a62d0,#5b47a8)] text-[13px] font-medium text-white transition hover:brightness-110"
            >
              {added ? (
                <>
                  <Check className="h-3.5 w-3.5" aria-hidden="true" />
                  Added
                </>
              ) : (
                <>
                  <ShoppingCart className="h-3.5 w-3.5" aria-hidden="true" />
                  Add to Cart
                </>
              )}
              <span className="sr-only"> — {product.title}</span>
            </button>
          </div>
        </div>
      </article>

      {mountedQuickView ? (
        <QuickViewDialog
          product={product}
          open={quickOpen}
          onClose={() => setQuickOpen(false)}
        />
      ) : null}
    </>
  );
}
