import type { ReactNode } from "react";
import type { BadgeId } from "@/lib/types";
import { badgeLabels, cn } from "@/lib/utils";

const tones = {
  violet: "border-violet-300/25 bg-violet-500/12 text-violet-200",
  gold: "border-gold-300/25 bg-gold-400/10 text-gold-200",
  azure: "border-azure-300/25 bg-azure-500/12 text-azure-200",
  silver: "border-white/12 bg-white/[0.05] text-silver-200",
} as const;

export type BadgeTone = keyof typeof tones;

const badgeTones: Record<BadgeId, BadgeTone> = {
  popular: "violet",
  starter: "azure",
  "best-value": "gold",
  premium: "gold",
  bespoke: "violet",
  new: "silver",
};

export function Badge({
  children,
  tone = "silver",
  className,
}: {
  children: ReactNode;
  tone?: BadgeTone;
  className?: string;
}) {
  return (
    <span
      className={cn(
        "inline-flex items-center gap-1.5 rounded-full border px-2.5 py-1 text-[11px] font-medium uppercase tracking-[0.12em]",
        tones[tone],
        className,
      )}
    >
      {children}
    </span>
  );
}

export function ProductBadge({
  badge,
  className,
}: {
  badge: BadgeId;
  className?: string;
}) {
  return (
    <Badge tone={badgeTones[badge]} className={className}>
      {badgeLabels[badge]}
    </Badge>
  );
}
