"use client";

import { useId, useState } from "react";
import { ChevronDown } from "lucide-react";
import { cn } from "@/lib/utils";

export interface AccordionEntry {
  id: string;
  question: string;
  answer: string;
}

export function Accordion({
  items,
  className,
  defaultOpenId,
}: {
  items: AccordionEntry[];
  className?: string;
  defaultOpenId?: string;
}) {
  const [openId, setOpenId] = useState<string | null>(defaultOpenId ?? null);
  const baseId = useId();

  return (
    <div className={cn("flex flex-col gap-2.5", className)}>
      {items.map((item) => {
        const open = openId === item.id;
        const buttonId = `${baseId}-${item.id}-button`;
        const panelId = `${baseId}-${item.id}-panel`;
        return (
          <div
            key={item.id}
            className={cn(
              "overflow-hidden rounded-xl border transition-colors",
              open
                ? "border-violet-300/25 bg-white/[0.035]"
                : "border-white/8 bg-white/[0.02] hover:border-white/16",
            )}
          >
            <h3>
              <button
                type="button"
                id={buttonId}
                aria-expanded={open}
                aria-controls={panelId}
                onClick={() => setOpenId(open ? null : item.id)}
                className="flex w-full items-center justify-between gap-4 px-4 py-4 text-left sm:px-5"
              >
                <span className="text-[14.5px] font-medium text-white sm:text-[15px]">
                  {item.question}
                </span>
                <ChevronDown
                  className={cn(
                    "h-4 w-4 shrink-0 text-silver-400 transition-transform duration-300",
                    open && "rotate-180 text-violet-200",
                  )}
                  aria-hidden="true"
                />
              </button>
            </h3>
            <div
              id={panelId}
              role="region"
              aria-labelledby={buttonId}
              hidden={!open}
              className="px-4 pb-4 sm:px-5 sm:pb-5"
            >
              <p className="text-[13.5px] leading-relaxed text-silver-300">
                {item.answer}
              </p>
            </div>
          </div>
        );
      })}
    </div>
  );
}
