"use client";

import Link from "next/link";
import {
  useCallback,
  useEffect,
  useMemo,
  useRef,
  useState,
  type CSSProperties,
  type PointerEvent as ReactPointerEvent,
} from "react";
import { useReducedMotion } from "framer-motion";
import { ArrowRight, ChevronLeft, ChevronRight, Clock, ShoppingCart } from "lucide-react";
import type { Product } from "@/lib/types";
import { ProductVisual } from "@/components/product/ProductVisual";
import { ProductBadge } from "@/components/ui/Badge";
import { PlatformIcons } from "@/components/product/PlatformIcons";
import { getCategoryTitle } from "@/config/categories";
import { useCart } from "@/lib/cart-context";
import { useUI } from "@/lib/ui-context";
import {
  createCartItem,
  defaultPlatform,
  defaultSelection,
} from "@/lib/product-utils";
import { cn, formatPrice } from "@/lib/utils";

/* ------------------------------------------------------------------ */
/* Geometry                                                            */
/* ------------------------------------------------------------------ */

interface Metrics {
  cardWidth: number;
  spacing: number;
  /** How far cards drop as they travel along the arc. */
  arcDepth: number;
  rotateY: number;
  /** Cards rendered on each side of the centre. */
  visibleSide: number;
  height: number;
}

function metricsFor(width: number): Metrics {
  if (width < 560) {
    return {
      cardWidth: 232,
      spacing: 176,
      arcDepth: 16,
      rotateY: 20,
      visibleSide: 2,
      height: 430,
    };
  }
  if (width < 900) {
    return {
      cardWidth: 268,
      spacing: 224,
      arcDepth: 24,
      rotateY: 22,
      visibleSide: 2,
      height: 470,
    };
  }
  if (width < 1280) {
    return {
      cardWidth: 300,
      spacing: 268,
      arcDepth: 30,
      rotateY: 24,
      visibleSide: 3,
      height: 500,
    };
  }
  return {
    cardWidth: 336,
    spacing: 312,
    arcDepth: 36,
    rotateY: 26,
    visibleSide: 3,
    height: 520,
  };
}

interface CardTransform {
  style: CSSProperties;
  dim: number;
  hidden: boolean;
}

function transformFor(offset: number, metrics: Metrics): CardTransform {
  const distance = Math.abs(offset);
  const hidden = distance > metrics.visibleSide + 0.6;
  const clamped = Math.max(
    -(metrics.visibleSide + 1),
    Math.min(metrics.visibleSide + 1, offset),
  );
  const absClamped = Math.abs(clamped);

  // Slight horizontal compression so distant cards tuck toward the edges.
  const x = Math.sign(clamped) * Math.pow(absClamped, 0.92) * metrics.spacing;
  // Curved path: cards ride down and back as they leave the centre.
  const y = Math.pow(absClamped, 1.55) * metrics.arcDepth;
  const z = -absClamped * 130;
  const rotateY = -clamped * metrics.rotateY;
  const rotateZ = clamped * 2.1;
  const scale = Math.max(0.58, 1 - absClamped * 0.135);
  const opacity = hidden ? 0 : Math.max(0, 1 - absClamped * 0.2);

  return {
    hidden,
    dim: Math.min(0.72, absClamped * 0.3),
    style: {
      width: metrics.cardWidth,
      transform: `translate3d(calc(-50% + ${x.toFixed(2)}px), ${y.toFixed(2)}px, ${z.toFixed(2)}px) rotateY(${rotateY.toFixed(2)}deg) rotateZ(${rotateZ.toFixed(2)}deg) scale(${scale.toFixed(3)})`,
      opacity,
      zIndex: 100 - Math.round(absClamped * 10),
      visibility: hidden ? "hidden" : "visible",
      pointerEvents: absClamped > metrics.visibleSide ? "none" : "auto",
    },
  };
}

/* ------------------------------------------------------------------ */
/* Component                                                           */
/* ------------------------------------------------------------------ */

export function ArcCarousel({ products }: { products: Product[] }) {
  const reduceMotion = useReducedMotion();
  const { addItem, currency } = useCart();
  const { carouselTarget, clearCarouselTarget } = useUI();

  const containerRef = useRef<HTMLDivElement>(null);
  const trackRef = useRef<HTMLDivElement>(null);
  const [metrics, setMetrics] = useState<Metrics>(() => metricsFor(1280));
  const [activeIndex, setActiveIndex] = useState(0);
  const [dragOffset, setDragOffset] = useState(0);
  const [dragging, setDragging] = useState(false);
  const [addedKey, setAddedKey] = useState<string | null>(null);

  const pointer = useRef({ id: -1, startX: 0, lastX: 0, lastTime: 0, velocity: 0 });
  const wheelAccumulator = useRef(0);
  const wheelLock = useRef(0);

  const count = products.length;

  const clampIndex = useCallback(
    (value: number) => Math.max(0, Math.min(count - 1, value)),
    [count],
  );

  const goTo = useCallback(
    (index: number) => setActiveIndex(clampIndex(index)),
    [clampIndex],
  );

  const next = useCallback(
    () => setActiveIndex((index) => clampIndex(index + 1)),
    [clampIndex],
  );
  const previous = useCallback(
    () => setActiveIndex((index) => clampIndex(index - 1)),
    [clampIndex],
  );

  /* Responsive metrics ------------------------------------------------ */
  useEffect(() => {
    const element = containerRef.current;
    if (!element) return;
    const update = () => setMetrics(metricsFor(element.clientWidth));
    update();
    const observer = new ResizeObserver(update);
    observer.observe(element);
    return () => observer.disconnect();
  }, []);

  /* Centre a product chosen from the search dialog ---------------------- */
  useEffect(() => {
    if (!carouselTarget) return;
    const index = products.findIndex((product) => product.slug === carouselTarget);
    if (index >= 0) setActiveIndex(index);
    clearCarouselTarget();
  }, [carouselTarget, products, clearCarouselTarget]);

  /* Wheel / trackpad ---------------------------------------------------
     Only horizontal intent (trackpad swipe or Shift+wheel) is captured, so a
     normal vertical wheel always keeps scrolling the page. */
  useEffect(() => {
    const element = containerRef.current;
    if (!element) return;

    function onWheel(event: WheelEvent) {
      const horizontal = Math.abs(event.deltaX) > Math.abs(event.deltaY);
      const shiftScroll = event.shiftKey && Math.abs(event.deltaY) > 0;
      if (!horizontal && !shiftScroll) return; // let the page scroll

      event.preventDefault();
      const delta = horizontal ? event.deltaX : event.deltaY;
      const now = performance.now();
      if (now - wheelLock.current < 220) return;

      wheelAccumulator.current += delta;
      if (Math.abs(wheelAccumulator.current) > 42) {
        wheelLock.current = now;
        setActiveIndex((index) =>
          clampIndex(index + (wheelAccumulator.current > 0 ? 1 : -1)),
        );
        wheelAccumulator.current = 0;
      }
    }

    element.addEventListener("wheel", onWheel, { passive: false });
    return () => element.removeEventListener("wheel", onWheel);
  }, [clampIndex]);

  /* Pointer drag / touch swipe ---------------------------------------- */
  const endDrag = useCallback(() => {
    if (pointer.current.id === -1) return;
    const travelled = pointer.current.lastX - pointer.current.startX;
    const velocity = pointer.current.velocity;
    const steps = -travelled / metrics.spacing;
    const flick = Math.abs(velocity) > 0.45 ? -Math.sign(velocity) * 0.55 : 0;

    setActiveIndex((index) => clampIndex(Math.round(index + steps + flick)));
    setDragOffset(0);
    setDragging(false);
    pointer.current.id = -1;
  }, [clampIndex, metrics.spacing]);

  function onPointerDown(event: ReactPointerEvent<HTMLDivElement>) {
    if (event.pointerType === "mouse" && event.button !== 0) return;
    pointer.current = {
      id: event.pointerId,
      startX: event.clientX,
      lastX: event.clientX,
      lastTime: performance.now(),
      velocity: 0,
    };
    setDragging(true);
  }

  function onPointerMove(event: ReactPointerEvent<HTMLDivElement>) {
    if (pointer.current.id !== event.pointerId) return;
    const now = performance.now();
    const dt = Math.max(1, now - pointer.current.lastTime);
    pointer.current.velocity = (event.clientX - pointer.current.lastX) / dt;
    pointer.current.lastX = event.clientX;
    pointer.current.lastTime = now;

    const travelled = event.clientX - pointer.current.startX;
    if (!dragging && Math.abs(travelled) > 4) setDragging(true);
    setDragOffset(-travelled / metrics.spacing);
  }

  function onPointerUp(event: ReactPointerEvent<HTMLDivElement>) {
    if (pointer.current.id !== event.pointerId) return;
    endDrag();
  }

  useEffect(() => {
    const cancel = () => endDrag();
    window.addEventListener("pointercancel", cancel);
    window.addEventListener("pointerup", cancel);
    return () => {
      window.removeEventListener("pointercancel", cancel);
      window.removeEventListener("pointerup", cancel);
    };
  }, [endDrag]);

  /* Keyboard ----------------------------------------------------------- */
  function onKeyDown(event: React.KeyboardEvent<HTMLDivElement>) {
    if (event.key === "ArrowRight") {
      event.preventDefault();
      next();
    } else if (event.key === "ArrowLeft") {
      event.preventDefault();
      previous();
    } else if (event.key === "Home") {
      event.preventDefault();
      goTo(0);
    } else if (event.key === "End") {
      event.preventDefault();
      goTo(count - 1);
    }
  }

  const transition = useMemo(
    () =>
      dragging || reduceMotion
        ? "none"
        : "transform 620ms cubic-bezier(.22,.61,.36,1), opacity 420ms ease",
    [dragging, reduceMotion],
  );

  const activeProduct = products[activeIndex];

  return (
    <div className="relative">
      {/* Stage ---------------------------------------------------------- */}
      <div
        ref={containerRef}
        role="group"
        aria-roledescription="carousel"
        aria-label="Featured packages"
        tabIndex={0}
        onKeyDown={onKeyDown}
        className="arc-perspective relative touch-pan-y select-none overflow-hidden rounded-2xl focus-visible:outline-2 focus-visible:outline-offset-4 focus-visible:outline-violet-300"
        style={{ height: metrics.height }}
      >
        {/* Arc guide line */}
        <div
          aria-hidden="true"
          className="pointer-events-none absolute inset-x-0 top-[62%] h-40 opacity-70"
          style={{
            background:
              "radial-gradient(60% 100% at 50% 0%, rgba(122,98,208,0.16), transparent 70%)",
          }}
        />

        <div
          ref={trackRef}
          onPointerDown={onPointerDown}
          onPointerMove={onPointerMove}
          onPointerUp={onPointerUp}
          className={cn(
            "absolute inset-0",
            dragging ? "cursor-grabbing" : "cursor-grab",
          )}
          style={{ transformStyle: "preserve-3d" }}
        >
          {products.map((product, index) => {
            const offset = index - activeIndex - dragOffset;
            const { style, dim, hidden } = transformFor(offset, metrics);
            const isActive = Math.round(activeIndex + dragOffset) === index;

            return (
              <div
                key={product.id}
                className="absolute left-1/2 top-[7%] origin-center will-change-transform"
                style={{ ...style, transition }}
                aria-hidden={hidden}
                inert={hidden || undefined}
              >
                <ArcCard
                  product={product}
                  active={isActive}
                  dim={dim}
                  currency={currency}
                  added={addedKey === product.id}
                  onSelect={() => {
                    if (!isActive) goTo(index);
                  }}
                  onAdd={() => {
                    addItem(
                      createCartItem(
                        product,
                        defaultPlatform(product),
                        defaultSelection(product),
                        1,
                      ),
                    );
                    setAddedKey(product.id);
                    window.setTimeout(() => setAddedKey(null), 1800);
                  }}
                />
              </div>
            );
          })}
        </div>

        {/* Edge fades */}
        <div
          aria-hidden="true"
          className="pointer-events-none absolute inset-y-0 left-0 w-16 bg-gradient-to-r from-[#050509] to-transparent sm:w-28"
        />
        <div
          aria-hidden="true"
          className="pointer-events-none absolute inset-y-0 right-0 w-16 bg-gradient-to-l from-[#050509] to-transparent sm:w-28"
        />
      </div>

      {/* Controls -------------------------------------------------------- */}
      <div className="mt-7 flex items-center justify-center gap-4 sm:gap-6">
        <button
          type="button"
          onClick={previous}
          disabled={activeIndex === 0}
          aria-label="Previous package"
          className="grid h-11 w-11 place-items-center rounded-full border border-white/12 bg-white/[0.03] text-silver-200 transition hover:border-violet-300/40 hover:bg-white/[0.08] hover:text-white disabled:opacity-30 disabled:hover:border-white/12"
        >
          <ChevronLeft className="h-5 w-5" aria-hidden="true" />
        </button>

        <div className="flex flex-col items-center gap-3">
          <p
            className="font-display text-[13px] tabular-nums tracking-[0.2em] text-silver-300"
            aria-live="polite"
          >
            <span className="text-white">
              {String(activeIndex + 1).padStart(2, "0")}
            </span>
            <span className="mx-1.5 text-silver-600">/</span>
            {String(count).padStart(2, "0")}
          </p>
          <ul className="flex items-center gap-1.5" role="tablist" aria-label="Choose package">
            {products.map((product, index) => (
              <li key={product.id}>
                <button
                  type="button"
                  role="tab"
                  aria-selected={index === activeIndex}
                  aria-label={`Show ${product.title}`}
                  onClick={() => goTo(index)}
                  className={cn(
                    "h-1.5 rounded-full transition-all duration-300",
                    index === activeIndex
                      ? "w-7 bg-gradient-to-r from-violet-300 to-gold-300"
                      : "w-1.5 bg-white/18 hover:bg-white/35",
                  )}
                />
              </li>
            ))}
          </ul>
        </div>

        <button
          type="button"
          onClick={next}
          disabled={activeIndex === count - 1}
          aria-label="Next package"
          className="grid h-11 w-11 place-items-center rounded-full border border-white/12 bg-white/[0.03] text-silver-200 transition hover:border-violet-300/40 hover:bg-white/[0.08] hover:text-white disabled:opacity-30 disabled:hover:border-white/12"
        >
          <ChevronRight className="h-5 w-5" aria-hidden="true" />
        </button>
      </div>

      <p className="mt-4 text-center text-[12px] text-silver-500">
        Drag, swipe, use the arrow keys or Shift + scroll to browse ·{" "}
        <Link
          href={`/products/${activeProduct?.slug ?? ""}`}
          className="text-silver-300 underline decoration-white/20 underline-offset-4 transition hover:text-white"
        >
          Open {activeProduct?.title}
        </Link>
      </p>
    </div>
  );
}

/* ------------------------------------------------------------------ */
/* Card                                                                */
/* ------------------------------------------------------------------ */

function ArcCard({
  product,
  active,
  dim,
  currency,
  added,
  onSelect,
  onAdd,
}: {
  product: Product;
  active: boolean;
  dim: number;
  currency: "USD" | "INR";
  added: boolean;
  onSelect: () => void;
  onAdd: () => void;
}) {
  return (
    <div
      className={cn(
        "relative overflow-hidden rounded-2xl border bg-[#0a0a11] transition-[border-color,box-shadow] duration-500",
        active
          ? "border-violet-300/30 shadow-[0_40px_90px_-45px_rgba(122,98,208,0.95)]"
          : "border-white/8",
      )}
    >
      {/* Clicking a side card brings it to the centre. */}
      {!active ? (
        <button
          type="button"
          onClick={onSelect}
          aria-label={`Bring ${product.title} to the centre`}
          className="absolute inset-0 z-20"
        />
      ) : null}

      <div className="relative aspect-4/3 overflow-hidden">
        <ProductVisual
          visual={product.visual}
          label={`${product.title} artwork`}
          className="h-full w-full"
        />
        {product.badge ? (
          <div className="absolute left-3 top-3">
            <ProductBadge badge={product.badge} />
          </div>
        ) : null}
      </div>

      <div className="flex flex-col gap-3 p-4">
        <div>
          <p className="text-[10px] font-medium uppercase tracking-[0.2em] text-violet-200/70">
            {getCategoryTitle(product.category)}
          </p>
          <h3 className="mt-1.5 text-[17px] font-semibold leading-tight text-white">
            {product.title}
          </h3>
          <p className="mt-1 line-clamp-2 text-[12.5px] leading-relaxed text-silver-400">
            {product.subtitle}
          </p>
        </div>

        <div className="flex items-center justify-between gap-2">
          <PlatformIcons platforms={product.supportedPlatforms} />
          <p className="shrink-0 text-[13.5px] font-semibold text-gold-200">
            {formatPrice(product.price, currency, product.quoteRequired)}
          </p>
        </div>

        <p className="inline-flex items-center gap-1.5 text-[11.5px] text-silver-500">
          <Clock className="h-3 w-3" aria-hidden="true" />
          {product.deliveryEstimate}
        </p>

        <div className="grid grid-cols-2 gap-2">
          <Link
            href={`/products/${product.slug}`}
            tabIndex={active ? undefined : -1}
            className="inline-flex h-10 items-center justify-center gap-1.5 rounded-lg border border-white/12 bg-white/[0.03] text-[12.5px] font-medium text-silver-100 transition hover:border-white/25 hover:bg-white/[0.08] hover:text-white"
          >
            View Product
            <ArrowRight className="h-3.5 w-3.5" aria-hidden="true" />
          </Link>
          <button
            type="button"
            onClick={onAdd}
            tabIndex={active ? undefined : -1}
            className="inline-flex h-10 items-center justify-center gap-1.5 rounded-lg border border-violet-400/40 bg-[linear-gradient(140deg,#7a62d0,#5b47a8)] text-[12.5px] font-medium text-white transition hover:brightness-110"
          >
            <ShoppingCart className="h-3.5 w-3.5" aria-hidden="true" />
            {added ? "Added" : "Add"}
            <span className="sr-only"> {product.title} to cart</span>
          </button>
        </div>
      </div>

      {/* Depth dimming for off-centre cards. */}
      <div
        aria-hidden="true"
        className="pointer-events-none absolute inset-0 bg-[#04040a] transition-opacity duration-500"
        style={{ opacity: dim }}
      />
    </div>
  );
}
