"use client";

import { AnimatePresence, motion, useReducedMotion } from "framer-motion";
import { useEffect, useState } from "react";
import { Logo } from "@/components/brand/Logo";
import { siteConfig } from "@/config/site";
import { useLockBodyScroll } from "@/lib/hooks";

const SEEN_KEY = "aether.intro.seen";

/**
 * Short cinematic intro shown once per browser session on the home page.
 *
 * It mounts after hydration (never rendered on the server) so it cannot cause
 * a hydration mismatch, and it is skipped entirely when the visitor prefers
 * reduced motion. Page content renders underneath, so crawlers and assistive
 * technology are never blocked.
 */
export function LoadingScreen() {
  const [visible, setVisible] = useState(false);
  const reduceMotion = useReducedMotion();

  useLockBodyScroll(visible);

  useEffect(() => {
    if (reduceMotion) return;
    let seen = false;
    try {
      seen = window.sessionStorage.getItem(SEEN_KEY) === "1";
    } catch {
      seen = false;
    }
    if (seen) return;

    setVisible(true);
    const timer = window.setTimeout(() => {
      setVisible(false);
      try {
        window.sessionStorage.setItem(SEEN_KEY, "1");
      } catch {
        /* ignore private-mode storage errors */
      }
    }, 1400);

    return () => window.clearTimeout(timer);
  }, [reduceMotion]);

  return (
    <AnimatePresence>
      {visible ? (
        <motion.div
          key="aether-intro"
          role="status"
          aria-live="polite"
          aria-label={`${siteConfig.name} is loading`}
          className="fixed inset-0 z-[300] grid place-items-center bg-[#050509]"
          initial={{ opacity: 1 }}
          exit={{ opacity: 0, filter: "blur(6px)" }}
          transition={{ duration: 0.55, ease: [0.22, 0.61, 0.36, 1] }}
        >
          <div
            aria-hidden="true"
            className="pointer-events-none absolute inset-0 bg-[radial-gradient(40rem_28rem_at_50%_45%,rgba(122,98,208,0.22),transparent_65%)]"
          />

          <div className="relative flex flex-col items-center">
            <motion.div
              initial={{ opacity: 0, scale: 0.88 }}
              animate={{ opacity: 1, scale: 1 }}
              transition={{ duration: 0.7, ease: [0.22, 0.61, 0.36, 1] }}
              className="relative"
            >
              <span
                aria-hidden="true"
                className="absolute -inset-6 rounded-full bg-violet-500/20 blur-2xl"
              />
              <Logo
                size={siteConfig.logo.sizes.loader}
                withWordmark={false}
                className="relative"
              />
            </motion.div>

            <motion.p
              initial={{ opacity: 0, y: 10 }}
              animate={{ opacity: 1, y: 0 }}
              transition={{ delay: 0.18, duration: 0.5 }}
              className="mt-6 font-display text-[26px] font-semibold tracking-[0.34em] text-white"
            >
              {siteConfig.name.toUpperCase()}
            </motion.p>

            <motion.p
              initial={{ opacity: 0 }}
              animate={{ opacity: 1 }}
              transition={{ delay: 0.32, duration: 0.5 }}
              className="mt-2 text-[11px] uppercase tracking-[0.3em] text-silver-500"
            >
              {siteConfig.tagline}
            </motion.p>

            <div className="relative mt-8 h-px w-52 overflow-hidden bg-white/10">
              <motion.span
                className="absolute inset-y-0 left-0 w-1/3 bg-gradient-to-r from-transparent via-violet-300 to-transparent"
                initial={{ x: "-120%" }}
                animate={{ x: "320%" }}
                transition={{ duration: 1.1, ease: "easeInOut", repeat: Infinity }}
              />
            </div>
          </div>
        </motion.div>
      ) : null}
    </AnimatePresence>
  );
}
